    // Favorites and checklists can be saved before the catalog is written to disk.
    // Keep seed numbers and existing ingredient positions stable across launches.
    private static func seed(_ number: UInt8, _ original: Recipe) -> Recipe {
        var recipe = original
        recipe.id = localSeedID(recipe: number, ingredient: 0)
        for index in recipe.ingredients.indices {
            recipe.ingredients[index].id = localSeedID(recipe: number, ingredient: UInt8(index + 1))
        }
        return recipe
    }

    private static func localSeedID(recipe: UInt8, ingredient: UInt8) -> UUID {
        UUID(uuid: (0xC1, 0xEF, 0x2A, 0x61, 0xD4, 0x3C, 0x40, 0x2D,
                    0xA2, 0x1B, 0x7C, 0x5B, 0x99, 0x68, recipe, ingredient))
    }

